func TestZZ2HandBackAndMarkerFailure(t *testing.T) {
	t.Setenv("TMPDIR", t.TempDir())
	for _, mode := range []string{"handback", "marker"} {
		root, s, prior := runContinuityFixture(t)
		plan, err := s.PlanReviewResume(prior.RunID)
		if err != nil {
			t.Fatal(err)
		}
		if mode == "handback" {
			plan.OnStart = func(string) error { return errors.New("no hand-back") }
		} else {
			matches, _ := filepath.Glob(filepath.Join(root, ".pose", "*", "*active*"))
			dirs := append(matches, filepath.Join(root, ".pose", "delegation-active"), filepath.Join(root, ".pose", "review-active"))
			for _, d := range dirs {
				_ = os.MkdirAll(d, 0o700)
				_ = os.WriteFile(filepath.Join(d, prior.AttemptID+".json"), []byte("{}"), 0o600)
			}
		}
		run, err := s.RunReviewDispatch(plan, time.Now)
		dir := filepath.Join(os.TempDir(), prior.Safety.RuntimeID)
		_, statErr := os.Lstat(dir)
		t.Logf("%s: status=%s failure=%q err=%v dirStat=%v", mode, run.Status, run.Failure, err, statErr)
		if mode == "handback" {
			_, herr := s.PlanReviewHandoff(run.RunID, "other")
			t.Logf("handoff of the failed continuation: %v", herr)
		}
	}
}

func TestZZ2RoundBesideLiveAndPlanRace(t *testing.T) {
	t.Setenv("TMPDIR", t.TempDir())
	marks := t.TempDir()
	root := dispatchInstance(t)
	agent := roundsAgent("rounder", "other", false)
	agent = strings.ReplaceAll(agent, "echo RESUMED-$1; ", "echo RESUMED-$1; if [ x$1 != x ] && mkdir "+marks+"/live; then i=0; while [ ! -e "+marks+"/release ] && [ $i -lt 200 ]; do sleep 0.1; i=$((i+1)); done; fi; ")
	if !strings.Contains(agent, marks) {
		t.Fatal("agent not patched")
	}
	writeDelegation(t, root, delegationPolicy(agent))
	first := runRecord(t, root, roundRun(t, root, "rounder")["run"].(string))
	nextReviewRound(t, root, "fix B1")
	s := posemodel.Store{Root: root}
	plan, err := s.PlanReviewDispatch("spec:alpha", "review", "", "rounder", "live round")
	if err != nil {
		t.Fatal(err)
	}
	done := make(chan string, 1)
	go func() {
		r, _ := s.RunReviewDispatch(plan, time.Now)
		done <- r.Status + " " + r.Safety.RuntimeID
	}()
	for i := 0; i < 100; i++ {
		if _, err := os.Stat(marks + "/live"); err == nil {
			break
		}
		time.Sleep(100 * time.Millisecond)
	}
	nextReviewRound(t, root, "fix B2")
	second := runRecord(t, root, roundRun(t, root, "rounder")["run"].(string))
	t.Logf("beside live: status=%s runtime=%s first=%s thread=%+v", second.Status, second.Safety.RuntimeID, first.Safety.RuntimeID, second.Thread)
	_ = os.WriteFile(marks+"/release", nil, 0o600)
	t.Logf("live run: %s", <-done)
	// A path taken between the plan and the dispatch.
	nextReviewRound(t, root, "fix B3")
	p, err := s.PlanReviewDispatch("spec:alpha", "review", "", "rounder", "race")
	if err != nil {
		t.Fatal(err)
	}
	held := filepath.Join(os.TempDir(), second.Safety.RuntimeID)
	if err := os.Mkdir(held, 0o700); err != nil {
		t.Fatal(err)
	}
	r, err := s.RunReviewDispatch(p, time.Now)
	t.Logf("after-plan: status=%s err=%v failure=%q", r.Status, err, r.Failure)
}
EOF
